G1 = zpk([-4],[-1 -2 -5],[1]) %[output:80dcc563]
%%
os = 20.8; %[output:6bd9c96b] %[output:0cc95b8d]
Ts = 4;
%%
a = 100/20.8
zeta = (a^2/(a^2 + pi^2))^0.5
%%
wn = 4/(Ts*zeta) %[output:595beb09]
%%
G2 = tf([1 2*wn*zeta wn^2],[1]) %[output:3cd568a4] %[output:841b015e]
%%
[num,den] = zp2tf([-4],[-1 -2 -5],[1]) %[output:375923ec] %[output:5fd2e3ca]
[A,B,C,D] = tf2ss(num,den) %[output:1addf301] %[output:4edd2742] %[output:9f05df52] %[output:277062dd]
T = [0 0 1 ; 0 1 0 ; 1 0 0] %[output:77644163]
A = T*A*inv(T) %[output:0d0df3ec]
B = T*B
K = place(A,B,[-5.4+7.2i -5.4-7.2i -5.1]). wn = 4/(Ts*zeta)

%%
rank(ctrb(A,B)) %[output:7eeefc94]
%%
 A=[-5 1 0;0 -2 1;0 0 -1];
 B=[0;0;1];
 C=[-1 1 0];
 D=0;
 pos=20.8;
 Ts=4 %[output:39bdb319]
 % Inputdesiredsettlingtime.
 z=(-log(pos/100))/(sqrt(pi^2+log(pos/100)^2));
 % Calculaterequireddampingratio.
 wn=4/(z*Ts);
 [num,den]=ord2(wn,z);
 r=roots(den);
 poles=[r(1) r(2) -4];
 K=acker(A,B,poles) %[output:7e995924]
 Anew=A-B*K;
 Bnew=B;
 Cnew=C;
 Dnew=D;
 Tss=ss(Anew,Bnew,Cnew,Dnew);
 'T(s)' %[output:44352f1b]
 T=tf(Tss);
 T=minreal(T) %[output:84b15449]
 poles=pole(T) %[output:851921db]
 step(Tss) %[output:488bd50a]
 title('Compensated Step Response') %[output:488bd50a]
%%


